def gather(root):
    groups = defaultdict(list)
    def add(owner, el, field, value):
        if not value or not re.search('[A-Za-z]',value) or owner in KEEP_OWNERS or ' '.join(value.split()) in KEEP:
            return
        if el.tag.endswith(('content-id','uuid')):
            return
        groups[owner].append((el,field,value))
    def walk(el,parent='document'):
        owner=el.get('id',parent)
        add(owner,el,'text',el.text)
        add(owner,el,'alt',el.get('alt'))
        for child in el:
            walk(child,owner)
        add(parent,el,'tail',el.tail)
    walk(root)
    return groups


def build(module, mapping):
    path=BASE/f'{module}.source.cnxml'
    assert hashlib.sha256(path.read_bytes()).hexdigest()==SHA[module]
    source=ET.parse(path).getroot()
    target=deepcopy(source)
    groups=gather(target)
    assert set(groups)==set(mapping), (set(groups)-set(mapping),set(mapping)-set(groups))
    for owner,slots in groups.items():
        assert len(slots)==len(mapping[owner]), (owner,len(slots),len(mapping[owner]))
        for (el,field,original),translated in zip(slots,mapping[owner]):
            lead=re.match(r'^\s*',original).group()
            tail=re.search(r'\s*$',original).group()
            if field=='alt': el.set(field,translated)
            else:setattr(el,field,lead+translated+tail)
    result=validate_pair(source,target)
    for owner in KEEP_OWNERS:
        src=source.find(f'.//*[@id="{owner}"]')
        dst=target.find(f'.//*[@id="{owner}"]')
        if src is not None:
            assert ET.tostring(src)==ET.tostring(dst), owner
    if module=='m81241':
        assert 'Copyright Rice University, OpenStax, under CC BY-NC-SA 4.0 license.' in ''.join(target.itertext())
    target.set('{http://www.w3.org/XML/1998/namespace}lang','gu-Gujr-IN')
    output=OUT/f'a00-{module}.gu.cnxml'
    ET.ElementTree(target).write(output,encoding='utf-8',xml_declaration=True)
    result.update({'module':module,'source_sha256':SHA[module],
                   'translated_slots':sum(map(len,groups.values())),
                   'media':sum(e.tag.endswith('}media') for e in source.iter()),
                   'output_sha256':hashlib.sha256(output.read_bytes()).hexdigest()})
    return result


if __name__=='__main__':
    print(json.dumps([build('m81241',PREFACE),build('m81242',INTRODUCTION)],indent=2))
